function toRelative(absolutePath) {
    if (!absolutePath) return '';

    // Normalize inputs
    let normalizedAbs = normalizeSeparators(absolutePath);
    let normalizedRoot = normalizeSeparators(PROJECT_ROOT);

    // Handle WSL /mnt/c vs C:/ mismatch
